799	Status SegmentHelper::MergeWithOptionalReuse(
800	    const std::string &output_index_path, const FieldSchema &index_field,
801	    std::vector<VectorColumnIndexer::Ptr> source_indexers,
802	    const IndexFilter::Ptr &filter, int concurrency,
803	    VectorColumnIndexer::Ptr *merged_indexer) {
804	  vector_column_params::MergeOptions merge_options;
805	  if (concurrency == 0) {
806	    merge_options.pool = GlobalResource::Instance().optimize_thread_pool();
807	    merge_options.write_concurrency =
808	        static_cast<uint32_t>(merge_options.pool->count());
809	  } else {
810	    merge_options.write_concurrency = concurrency;
811	  }
812	  auto vector_indexer =
813	      std::make_shared<VectorColumnIndexer>(output_index_path, index_field);
814	  bool reused_base_index = false;
815	  Status s;
816	
817	  if (CanReuseFirstIndexer(source_indexers, index_field, filter)) {
818	    const auto &first_indexer = source_indexers.front();
819	    LOG_INFO(
820	        "Reusing first indexer as merge base. "
821	        "field[%s] src[%s] dst[%s] tail_indexers[%zu]",
822	        index_field.name().c_str(), first_indexer->index_file_path().c_str(),
823	        output_index_path.c_str(), source_indexers.size() - 1);
824	    if (FileHelper::CopyFile(first_indexer->index_file_path(),
825	                             output_index_path)) {
826	      // Open the copied file in-place (create_new=false).
827	      s = vector_indexer->open(vector_column_params::ReadOptions{true, false});
828	      CHECK_RETURN_STATUS(s);
829	
830	      source_indexers.erase(source_indexers.begin());
831	      s = vector_indexer->merge(source_indexers, filter, merge_options);
832	      CHECK_RETURN_STATUS(s);
833	      reused_base_index = true;
834	    } else {
835	      LOG_WARN("Failed to copy %s to %s; falling back to full rebuild",
836	               first_indexer->index_file_path().c_str(),
837	               output_index_path.c_str());
838	    }
839	  }
