34	template <IndexMeta::DataType DT, typename T>
35	int MaterializeMergedInput(const MergedProviderIndexHolder::Pointer &source,
36	                           IndexHolder::Pointer *output) {
37	  auto snapshot =
38	      std::make_shared<MultiPassIndexHolder<DT>>(source->dimension());
39	  snapshot->reserve(source->count());
40	  auto iter = source->create_iterator();
41	  if (!iter) {
42	    return source->status() != 0 ? source->status() : IndexError_Runtime;
43	  }
44	  for (; iter->is_valid(); iter->next()) {
45	    const void *data = iter->data();
46	    if (iter->status() != 0) {
47	      return iter->status();
48	    }
49	    if (source->status() != 0) {
50	      return source->status();
51	    }
52	    if (!data) {
53	      return IndexError_ReadData;
54	    }
55	    ailego::NumericalVector<T> vector(source->dimension());
56	    std::memcpy(vector.data(), data, source->element_size());
57	    const uint64_t key = iter->key();
58	    if (iter->status() != 0) {
59	      return iter->status();
60	    }
61	    if (!snapshot->emplace(key, std::move(vector))) {
62	      return IndexError_Mismatch;
63	    }
64	  }
65	  if (iter->status() != 0) {
66	    return iter->status();
67	  }
68	  if (source->status() != 0) {
69	    return source->status();
70	  }
71	  if (snapshot->count() != source->count()) {
72	    return IndexError_Mismatch;
73	  }
74	  *output = std::move(snapshot);
75	  return 0;
76	}
